INSERT INTO news_online.news(news_id, article_id, header_news, is_published, short_description, author_id, category_id)
VALUES ('a03bd6ce-123d-4b73-8d24-6324971d0a67', 8918718, 'Почему все хотят попасть на Щелкунчика', true, '«„Щелкунчик“ — это гениальное произведение». Закулисье самого ожидаемого балета года', '5cad6fef-b248-4035-839c-dc78ffad5623', '25f4f0cc-95ca-4622-9640-3de7a82cded9'),
       ('3f0a9ddd-9004-4b23-934a-f0abf4706cca', 9261412, 'Цель на 2025 - Выйти замуж. О чем мечтают белорусы.', true, '«В канун Нового года мы ждем елку, мандарины и, конечно же, мечтаем. Кто-то из нас хочет сняться в сериале, кто-то — собраться с силами и, наконец, пойти в спортзал, еще кто-то — обзавестись жильем. Вместе со «Спортмастером» расспросили белорусов об их самых заветных желаниях и отправили их Деду Морозу, чтобы все сбылось наверняка.', 'c09fa0f9-5513-4c97-b80b-c81f0667b21c', '25f4f0cc-95ca-4622-9640-3de7a82cded9'),
       ('9e42e414-99f2-442f-9ad1-73d67ee62d05', 8792469, 'Топ-10 (и еще немного) лучших сериалов 2024 года по версии подкаста «Прослушка»', true, '« Итак, встречайте новогодний выпуск и десятку лучших сериалов года по версии «Прослушки». Лондонская сталкерша, социопаты-гедонисты, пятеро Робертов Дауни — младших, готэмские мафиози, японские феодалы и снова игроки «в кальмара» — в общем, здесь все, что вы ожидаете и что не очень.', '1a041c98-0a17-42e2-888a-f29d97a8d353', '25f4f0cc-95ca-4622-9640-3de7a82cded9'),
       ('7753980b-dda9-428c-b1f0-58bc4d24e138', 3482264, 'Постараемся обойтись без «китайцев». Ищем подержанные электромобили', true, 'Хит сезона — новые или слегка подержанные «электрички» из Китая. Но на этот же бюджет можно поискать и более возрастные модели западных брендов. Посмотрели на «Автобарахолке» электромобили не старше 2019 года выпуска.', 'c09fa0f9-5513-4c97-b80b-c81f0667b21c', '3de78717-14f5-491e-a375-e122ec4dcbe2'),
       ('8ab2519d-29b5-4be8-b89f-771c1d308b13', 6482701, 'На базе Lada Vesta построят минивэн. Новые подробности', true, 'Сейчас «АвтоВАЗ» активно работает над запуском производства бюджетной модели Iskra, которая должна выйти на рынок уже в этом году. Далее по планам кроссовер на базе Vesta — его покажут этим летом, а продажи должны стартовать в 2026 году. А вот затем придет очередь минивэна.', '1a041c98-0a17-42e2-888a-f29d97a8d353', '3de78717-14f5-491e-a375-e122ec4dcbe2'),
       ('394a15c3-5115-4dcd-ae71-75abaf1bffa4', 5666418, 'В Казахстане массовая авария: столкнулись 95 автомобилей', true, 'Как сообщает Telegram-канал местного национального оператора по управлению автомобильными дорогами страны «КазАвтоЖол», все случилось около 13:28 на 153-м километре трассы Астана — Петропавловск, в районе села Жанаталап. Причиной называют несоблюдение водителями скоростного режима и безопасной дистанции.', '5cad6fef-b248-4035-839c-dc78ffad5623',  '3de78717-14f5-491e-a375-e122ec4dcbe2'),
       ('db7e3e88-f479-4e7d-b6c6-c9bf6a1c8f23', 4951701, 'Жители одной из высоток «Минск-Мира» воссоздали в своем доме… весь «Минск-Мир»', true, 'Еще десять лет назад украшать подъезды было совершенно не принято. На весь город можно было отыскать лишь пару мест общего пользования с гирляндами и елочками. И те смотрелись как некая диковинка: придумают же люди. Со временем все изменилось. И, думается, немалую роль в этом сыграли застройщики, которые начали возводить дома с изначально красивыми лобби. Добавь к ним пару новогодних штрихов — и уже хорошо. А если постараться…',  'c09fa0f9-5513-4c97-b80b-c81f0667b21c',  '023f9d67-cc80-4bbe-9267-fbbff35e3ea1'),
       ('155dfa4d-4529-44a7-8834-26909df89213', 7656706, 'Смотрите, какой таунхаус построят под Минском, недалеко от гольф-полей. Цена — от $1900 за «квадрат»', true, 'В «Зеленой гавани» под Минском построят двухэтажный таунхаус, который станет последним в квартале «Долина холмов». По проекту в нем будет всего пять квартир, но зато каких! Рассказываем, сколько будет стоить «квадрат» в современном таунхаусе вблизи гольф-полей.', '1a041c98-0a17-42e2-888a-f29d97a8d353', '023f9d67-cc80-4bbe-9267-fbbff35e3ea1'),
       ('f501c953-7439-45e2-af39-2c1b63c6b882', 7029846, 'Арендодатель впервые за два года навестил квартиру и обнаружил, что жилец превратил ее в курятник', true, 'Владелец квартиры в китайском Шанхае пребывает в глубоком шоке после того, как после долгого перерыва навестил свою собственность. Оказалось, что арендатор устроил в жилье курятник с соответствующей грязью и запахом. Теперь хозяин будет вынужден делать в квартире ремонт.', '5cad6fef-b248-4035-839c-dc78ffad5623', '023f9d67-cc80-4bbe-9267-fbbff35e3ea1'),
       ('193fc39b-e7b9-488c-8f8b-06685833a113', 6840990, '«40 лет на третьем этаже». Как трудятся и зарабатывают мастера из дома быта', true, 'Заточить ножи, починить обувь, отстирать любимую вещь, подстричься или зашить порванную рубашку — мы привыкли бегать по разным местам, решая бытовые вопросы. А что если все это можно сделать за один раз и в одном здании? Таких локаций, где все услуги собраны под одной крышей, у нас хватает.', 'c09fa0f9-5513-4c97-b80b-c81f0667b21c', '9bcee973-81ac-488e-936b-7fad4ea0bc55'),
       ('e1f8a95f-6735-487e-86dc-fca676ec2f3c', 3733678, '«У меня был только робот-пылесос, теперь и палка будет».', true, 'Мы спросили у наших читателей, чем порадовали их работодатели к Новому году. Одним достались подарки, о которых мечтаешь весь год, другим — как будто из категории «лишь бы что-то подарить». Все самое интересное мы собрали в этом материале.', '1a041c98-0a17-42e2-888a-f29d97a8d353', '9bcee973-81ac-488e-936b-7fad4ea0bc55'),
       ('8d72d87b-39a6-49a8-bc9c-99c439edb0d7', 1936999, '«Семья полтора года откладывала монеты в банку. Сколько накопила?».', true, 'Способом накопления денег в банке — но не в том, что с карточками и очередями, а в обычной стеклянной таре — поделилась белорусская семья в TikTok. Эксперимент завершился спустя полтора года: они насобирали полтора литра монет, наконец вскрыли копилку и посчитали сбережения.', '5cad6fef-b248-4035-839c-dc78ffad5623', '9bcee973-81ac-488e-936b-7fad4ea0bc55'),
       ('6c06d779-cbe1-4350-92c2-ec4aa3059b98', 2368601, '«Инсайдер назвал TDP видеокарт RTX 5090 и RTX 5080 — они заметно подросли.', true, 'Инсайдер hongxing202 раскрыл информацию о TDP официально не анонсированных видеокарт NVIDIA RTX 5090 и RTX 5080. Как следует из озвученных им данных, TDP для RTX 5090 составит 575 Ватт, что на 125 Ватт выше, чем у RTX 4090. TDP RTX 5080, в свою очередь, составляет 360 Ватт.', 'c09fa0f9-5513-4c97-b80b-c81f0667b21c', 'ff906a3c-3f94-4c0c-9370-56d37046c6d0'),
       ('ebaf483e-690e-4ce4-90de-1809d6c4cadf', 8374569, '«На видео показали портативную консоль Atari Gamestation Go', true, 'На грядущей выставке CES 2025 будет представлена портативная игровая консоль Atari Gamestation Go, пока же в сети появился небольшой видеотизер, посвященный новинке. К сожалению, информации о характеристиках, возможностях и цене Atari Gamestation Go на данный момент нет.', '1a041c98-0a17-42e2-888a-f29d97a8d353', 'ff906a3c-3f94-4c0c-9370-56d37046c6d0'),
       ('1eddc742-426d-400b-b57b-7f8c9719ea0f', 1951214, '«Honor представила «облегченную» версию флагмана — смартфон Magic7 Lite с огромной батареей', true, 'Honor представила смартфон среднего уровня Magic7 Lite на базе чипа Snapdragon 6 Gen 1 и с батареей емкостью 6600 мАч (последний аспект является основным аппаратным отличием от прошлогоднего Magic6 Lite с его аккумулятором на 5300 мАч). Как утверждает производитель, 2% заряда аккумулятора достаточно для 50 минут работы.', '5cad6fef-b248-4035-839c-dc78ffad5623', 'ff906a3c-3f94-4c0c-9370-56d37046c6d0'),
       ('c342a38c-7ff8-4abb-9b45-da294f868d48', 7745462, 'Сколько излучают смартфоны в 5G?', true, 'Исследователи из Швейцарии и Испании в рамках инициативы Project GOLIAT разработали методику измерения уровня излучения 5G-смартфонов. Исследования проводились на территории Швейцарии, где существует обширная сеть нового поколения. Интенсивность излучения измеряли в трех сценариях: когда смартфоны находятся в «режиме полета», во время активной загрузки данных и их отправке.', 'c09fa0f9-5513-4c97-b80b-c81f0667b21c', 'ff906a3c-3f94-4c0c-9370-56d37046c6d0'),
       ('077a07ae-cd7e-48d8-b38e-3d7b54ef5803', 5695051, 'Власти Японии просят туристов не ехать в Токио и Киото. В качестве замены предлагают сельскую местность', true, 'Совет по туризму Японии призвал отдыхающих поменять Токио и Киото на другие города — Тохоку и Канадзава. Причиной такого решения стали австралийцы, который буквально наводнили самые популярные туристические места, пишет Guardian.', '1a041c98-0a17-42e2-888a-f29d97a8d353', '5a8f24a5-dd1c-41c9-b749-6e638c736f1a'),
       ('367ebbb8-3611-4129-bd9b-57cf3f386075', 5679011, 'Таиланд разрешил белорусам получать электронные визы. Но сходить в консульство все равно придется', true, 'С 1 января Таиланд меняет визовые правила для белорусов: теперь для длительных (больше 2 недель) поездок в страну туристам нужно будет получить электронную визу за $40. Правда, от похода в консульство это пока не освободит.', '5cad6fef-b248-4035-839c-dc78ffad5623', '5a8f24a5-dd1c-41c9-b749-6e638c736f1a'),
       ('db42d060-8c73-433e-98b6-f18c62cfbd5a', 1850134, 'Из Минска прямым рейсом можно будет слетать в популярный у туристов регион Китая. Уже в декабре', true, 'Вылеты вечерние, в 20:40. Время в пути составит 8 часов 20 минут, то есть в Сиане окажетесь только утром воскресенья. Билет в экономкласс (в одну сторону) стоит не такие уж экономные 564 евро — для прямых перелетов в самый центр Азии, впрочем, цена вполне стандартная.',  '5cad6fef-b248-4035-839c-dc78ffad5623', '5a8f24a5-dd1c-41c9-b749-6e638c736f1a');
--changeset ivan101454:5
